-- Независим календар на одиторите, импортиран от „календар одитори 2026.xlsx“.

create table if not exists public.auditor_calendar_auditors (
  id text primary key,
  name text not null unique,
  color text not null check (color ~ '^#[0-9A-Fa-f]{6}$'),
  sort_order integer not null default 0,
  created_by uuid references public.profiles(id),
  updated_by uuid references public.profiles(id),
  updated_at timestamptz not null default now(),
  created_at timestamptz not null default now()
);

create table if not exists public.auditor_calendar_entries (
  id text primary key,
  event_date date not null,
  company_name text not null,
  details text,
  auditor_id text not null references public.auditor_calendar_auditors(id) on delete restrict,
  source_sheet text,
  source_cell text,
  sort_order integer not null default 0,
  created_by uuid references public.profiles(id),
  updated_by uuid references public.profiles(id),
  updated_at timestamptz not null default now(),
  created_at timestamptz not null default now(),
  unique (source_sheet, source_cell)
);

create index if not exists auditor_calendar_entries_date_idx
  on public.auditor_calendar_entries(event_date);

create index if not exists auditor_calendar_entries_auditor_idx
  on public.auditor_calendar_entries(auditor_id);

create index if not exists auditor_calendar_auditors_created_by_idx
  on public.auditor_calendar_auditors(created_by);
create index if not exists auditor_calendar_auditors_updated_by_idx
  on public.auditor_calendar_auditors(updated_by);
create index if not exists auditor_calendar_entries_created_by_idx
  on public.auditor_calendar_entries(created_by);
create index if not exists auditor_calendar_entries_updated_by_idx
  on public.auditor_calendar_entries(updated_by);

alter table public.auditor_calendar_auditors enable row level security;
alter table public.auditor_calendar_entries enable row level security;

drop policy if exists "authenticated users can read auditor calendar auditors" on public.auditor_calendar_auditors;
create policy "authenticated users can read auditor calendar auditors" on public.auditor_calendar_auditors
  for select to authenticated using (true);

drop policy if exists "authenticated users can write auditor calendar auditors" on public.auditor_calendar_auditors;
drop policy if exists "authenticated users can insert auditor calendar auditors" on public.auditor_calendar_auditors;
create policy "authenticated users can insert auditor calendar auditors" on public.auditor_calendar_auditors
  for insert to authenticated with check (true);
drop policy if exists "authenticated users can update auditor calendar auditors" on public.auditor_calendar_auditors;
create policy "authenticated users can update auditor calendar auditors" on public.auditor_calendar_auditors
  for update to authenticated using (true) with check (true);
drop policy if exists "authenticated users can delete auditor calendar auditors" on public.auditor_calendar_auditors;
create policy "authenticated users can delete auditor calendar auditors" on public.auditor_calendar_auditors
  for delete to authenticated using (true);

drop policy if exists "authenticated users can read auditor calendar entries" on public.auditor_calendar_entries;
create policy "authenticated users can read auditor calendar entries" on public.auditor_calendar_entries
  for select to authenticated using (true);

drop policy if exists "authenticated users can write auditor calendar entries" on public.auditor_calendar_entries;
drop policy if exists "authenticated users can insert auditor calendar entries" on public.auditor_calendar_entries;
create policy "authenticated users can insert auditor calendar entries" on public.auditor_calendar_entries
  for insert to authenticated with check (true);
drop policy if exists "authenticated users can update auditor calendar entries" on public.auditor_calendar_entries;
create policy "authenticated users can update auditor calendar entries" on public.auditor_calendar_entries
  for update to authenticated using (true) with check (true);
drop policy if exists "authenticated users can delete auditor calendar entries" on public.auditor_calendar_entries;
create policy "authenticated users can delete auditor calendar entries" on public.auditor_calendar_entries
  for delete to authenticated using (true);

grant select, insert, update, delete on public.auditor_calendar_auditors to authenticated;
grant select, insert, update, delete on public.auditor_calendar_entries to authenticated;

insert into public.auditor_calendar_auditors (id, name, color, sort_order)
